using System;
using System.Collections.Generic;
using System.Linq;
using Grasshopper.Kernel;
using Rhino.Geometry;

namespace BenchPlugin
{
    public class ShelfPackComponent : GH_Component
    {
        public ShelfPackComponent()
            : base("Shelf Pack", "ShelfPack", "Packs rectangular parts onto rectangular sheets with a shelf algorithm", "Bench", "Fabrication")
        {
        }

        public override Guid ComponentGuid => new Guid("5e8b0c36-2d71-4f4a-9a63-b1d7c4e82f05");

        protected override void RegisterInputParams(GH_InputParamManager pManager)
        {
            pManager.AddNumberParameter("Widths", "W", "Part widths", GH_ParamAccess.list);
            pManager.AddNumberParameter("Heights", "H", "Part heights (part i is Widths[i] by Heights[i])", GH_ParamAccess.list);
            pManager.AddNumberParameter("Sheet Width", "SW", "Sheet width", GH_ParamAccess.item, 1000.0);
            pManager.AddNumberParameter("Sheet Height", "SH", "Sheet height", GH_ParamAccess.item, 500.0);
            pManager.AddNumberParameter("Spacing", "S", "Gap between parts and from the sheet edge", GH_ParamAccess.item, 5.0);
            pManager.AddBooleanParameter("Rotate", "R", "Allow turning parts by 90 degrees", GH_ParamAccess.item, true);
        }

        protected override void RegisterOutputParams(GH_OutputParamManager pManager)
        {
            pManager.AddCurveParameter("Outlines", "O", "Outline of each placed part", GH_ParamAccess.list);
            pManager.AddIntegerParameter("Sheet", "S", "Sheet index of each placed part", GH_ParamAccess.list);
            pManager.AddIntegerParameter("Sheet Count", "C", "Number of sheets used", GH_ParamAccess.item);
            pManager.AddNumberParameter("Utilization", "U", "Placed part area / (Sheet Count * sheet area)", GH_ParamAccess.item);
            pManager.AddIntegerParameter("Unplaced", "X", "Input indices of parts that were left out", GH_ParamAccess.list);
        }

        protected override void SolveInstance(IGH_DataAccess DA)
        {
            var widths = new List<double>();
            var heights = new List<double>();
            double sheetW = 1000.0, sheetH = 500.0, spacing = 5.0;
            bool rotate = true;

            if (!DA.GetDataList(0, widths)) return;
            if (!DA.GetDataList(1, heights)) return;
            DA.GetData(2, ref sheetW);
            DA.GetData(3, ref sheetH);
            DA.GetData(4, ref spacing);
            DA.GetData(5, ref rotate);

            if (widths.Count != heights.Count)
            {
                AddRuntimeMessage(GH_RuntimeMessageLevel.Error, "Widths and Heights must have the same length.");
                return;
            }
            if (widths.Any(v => v <= 0) || heights.Any(v => v <= 0) || sheetW <= 0 || sheetH <= 0)
            {
                AddRuntimeMessage(GH_RuntimeMessageLevel.Error, "All sizes must be greater than zero.");
                return;
            }
            if (spacing < 0)
            {
                AddRuntimeMessage(GH_RuntimeMessageLevel.Error, "Spacing must not be negative.");
                return;
            }

            double maxX = sheetW - spacing;
            double maxY = sheetH - spacing;

            var order = Enumerable.Range(0, widths.Count)
                .OrderByDescending(i => heights[i])
                .ToList();

            var outlines = new List<Curve>();
            var sheets = new List<int>();
            var unplaced = new List<int>();
            double placedArea = 0;

            int sheet = -1;
            double cursorX = 0, shelfY = 0, shelfH = 0;

            foreach (int i in order)
            {
                var options = new List<(double w, double h)> { (widths[i], heights[i]) };
                if (rotate) options.Add((heights[i], widths[i]));

                if (!options.Any(o => spacing + o.w <= maxX && spacing + o.h <= maxY))
                {
                    unplaced.Add(i);
                    continue;
                }

                double px = 0, py = 0, pw = 0, ph = 0;
                bool placed = false;

                if (sheet >= 0)
                {
                    // rest of the current shelf
                    foreach (var o in options)
                    {
                        if (cursorX + o.w <= maxX && o.h <= shelfH)
                        {
                            px = cursorX; py = shelfY; pw = o.w; ph = o.h;
                            cursorX += o.w + spacing;
                            placed = true;
                            break;
                        }
                    }

                    // new shelf above
                    if (!placed)
                    {
                        double newY = shelfY + shelfH + spacing;
                        foreach (var o in options)
                        {
                            if (spacing + o.w <= maxX && newY + o.h <= maxY)
                            {
                                shelfY = newY; shelfH = o.h;
                                px = spacing; py = shelfY; pw = o.w; ph = o.h;
                                cursorX = spacing + o.w + spacing;
                                placed = true;
                                break;
                            }
                        }
                    }
                }

                // new sheet
                if (!placed)
                {
                    foreach (var o in options)
                    {
                        if (spacing + o.w <= maxX && spacing + o.h <= maxY)
                        {
                            sheet++;
                            shelfY = spacing; shelfH = o.h;
                            px = spacing; py = spacing; pw = o.w; ph = o.h;
                            cursorX = spacing + o.w + spacing;
                            break;
                        }
                    }
                }

                double ox = sheet * (sheetW + 50.0);
                var pl = new Polyline(new[]
                {
                    new Point3d(ox + px, py, 0),
                    new Point3d(ox + px + pw, py, 0),
                    new Point3d(ox + px + pw, py + ph, 0),
                    new Point3d(ox + px, py + ph, 0),
                    new Point3d(ox + px, py, 0),
                });
                outlines.Add(new PolylineCurve(pl));
                sheets.Add(sheet);
                placedArea += widths[i] * heights[i];
            }

            int sheetCount = sheet + 1;
            double utilization = sheetCount > 0 ? placedArea / (sheetCount * sheetW * sheetH) : 0.0;

            if (unplaced.Count > 0)
            {
                unplaced.Sort();
                AddRuntimeMessage(GH_RuntimeMessageLevel.Warning, unplaced.Count + " part(s) did not fit on a sheet and were left out.");
            }

            DA.SetDataList(0, outlines);
            DA.SetDataList(1, sheets);
            DA.SetData(2, sheetCount);
            DA.SetData(3, utilization);
            DA.SetDataList(4, unplaced);
        }
    }
}
EOF
